//! The standard dates, computed for a person from what ships with the bridge: clock changes from the tz database
//! built in (chrono-tz), public holidays per country and region (`assets/dates/holidays.json`, from the `holidays`
//! library, MIT), French school holidays per zone (`assets/dates/school_fr.json`, the ministry's « Calendrier
//! scolaire », Licence Ouverte). Generated by `scripts/standard-dates.py`; nothing is fetched at runtime and nothing
//! is stored per person.

use std::collections::BTreeMap;
use std::sync::LazyLock;

use chrono::{DateTime, Duration, NaiveDate, NaiveDateTime, NaiveTime, Offset, TimeZone, Utc};
use chrono_tz::Tz;
use indexmap::IndexMap;
use serde::Deserialize;
use serde_json::{json, Value};

use super::words::{self, SchoolDay};

static HOLIDAYS_JSON: &str = include_str!("../../assets/dates/holidays.json");
static SCHOOL_JSON: &str = include_str!("../../assets/dates/school_fr.json");

#[derive(Debug, Deserialize)]
pub struct Holidays {
    pub meta: Value,
    pub countries: BTreeMap<String, Country>,
}

#[derive(Debug, Deserialize)]
pub struct Country {
    /// The language of the « local » names.
    pub language: String,
    pub subdivisions: IndexMap<String, String>,
    pub holidays: Vec<Holiday>,
}

#[derive(Debug, Deserialize)]
pub struct Holiday {
    pub date: String,
    /// « local », and « fr », « en », « de », « es » where the library has them.
    pub names: BTreeMap<String, String>,
    /// Only in these regions; none: the whole country.
    #[serde(default)]
    pub only: Vec<String>,
}

impl Holiday {
    /// Its name in `lang`: the translation, the local name when it is that language, else the English one.
    pub fn name(&self, lang: &str, country_language: &str) -> String {
        let local = self.names.get("local").cloned().unwrap_or_default();
        if let Some(name) = self.names.get(lang) {
            return name.clone();
        }
        if country_language == lang {
            return local;
        }
        self.names.get("en").cloned().unwrap_or(local)
    }
}

#[derive(Debug, Deserialize)]
pub struct School {
    pub meta: Value,
    pub zones: BTreeMap<String, Vec<Period>>,
}

#[derive(Debug, Deserialize)]
pub struct Period {
    pub name: String,
    /// The first day off.
    pub start: String,
    /// The day classes resume (the same day: a single day off).
    pub end: String,
}

pub static HOLIDAYS: LazyLock<Holidays> =
    LazyLock::new(|| serde_json::from_str(HOLIDAYS_JSON).expect("assets/dates/holidays.json is valid"));
pub static SCHOOL: LazyLock<School> =
    LazyLock::new(|| serde_json::from_str(SCHOOL_JSON).expect("assets/dates/school_fr.json is valid"));

fn date(text: &str) -> Option<NaiveDate> {
    NaiveDate::parse_from_str(text, "%Y-%m-%d").ok()
}

/// What the dates are computed for: the person's zone, country, region and French school zone.
#[derive(Debug, Clone)]
pub struct For {
    pub zone: Tz,
    pub country: Option<String>,
    pub region: Option<String>,
    pub school_zone: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    ClockChange,
    Holiday,
    School,
}

impl Kind {
    pub fn code(self) -> &'static str {
        match self {
            Kind::ClockChange => "clock_change",
            Kind::Holiday => "holiday",
            Kind::School => "school",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Item {
    pub date: NaiveDate,
    pub kind: Kind,
    pub text: String,
}

impl Item {
    pub fn view(&self, today: NaiveDate, lang: &str) -> Value {
        json!({"date": self.date.format("%Y-%m-%d").to_string(), "in_days": (self.date - today).num_days(),
               "kind": self.kind.code(), "text": self.text, "day": words::day(self.date, lang)})
    }
}

fn offset_at(zone: Tz, at: DateTime<Utc>) -> i32 {
    zone.offset_from_utc_datetime(&at.naive_utc()).fix().local_minus_utc()
}

/// A clock change: the day and wall-clock time it happens at (on the old clock), and by how much (seconds, > 0:
/// forward).
#[derive(Debug, Clone, PartialEq)]
pub struct Change {
    pub at: NaiveDateTime,
    pub delta: i32,
}

/// The clock changes of `zone` whose local day is in `first..=last`.
pub fn clock_changes(zone: Tz, first: NaiveDate, last: NaiveDate) -> Vec<Change> {
    let mut out = Vec::new();
    let Some(start) = first.and_hms_opt(0, 0, 0) else { return out };
    let Some(end) = last.and_hms_opt(0, 0, 0) else { return out };
    // UTC hours from a day before to a day after: every zone's midnight is inside
    let mut t = Utc.from_utc_datetime(&(start - Duration::days(1)));
    let stop = Utc.from_utc_datetime(&(end + Duration::days(2)));
    let mut before = offset_at(zone, t);
    while t < stop {
        let next = t + Duration::hours(1);
        let after = offset_at(zone, next);
        if after != before {
            // the first minute on the new offset
            let (mut low, mut high) = (t, next);
            while high - low > Duration::minutes(1) {
                let mid = low + (high - low) / 2;
                if offset_at(zone, mid) == before {
                    low = mid;
                } else {
                    high = mid;
                }
            }
            let at = high.naive_utc() + Duration::seconds(i64::from(before));
            if (first..=last).contains(&at.date()) {
                out.push(Change { at, delta: after - before });
            }
            before = after;
        }
        t = next;
    }
    out
}

/// Public holidays of the country (and its region's) whose day is in `first..=last`.
fn holidays(who: &For, first: NaiveDate, last: NaiveDate, lang: &str) -> Vec<Item> {
    let Some(code) = who.country.as_deref() else { return Vec::new() };
    let Some(country) = HOLIDAYS.countries.get(code) else { return Vec::new() };
    let region = who.region.as_deref().filter(|r| country.subdivisions.contains_key(*r));
    let mut out: Vec<Item> = Vec::new();
    for holiday in &country.holidays {
        let Some(day) = date(&holiday.date) else { continue };
        if day < first || day > last {
            continue;
        }
        let regional = !holiday.only.is_empty();
        if regional && !region.is_some_and(|r| holiday.only.iter().any(|o| o == r)) {
            continue;
        }
        let name = holiday.name(lang, &country.language);
        let region_name =
            if regional { region.and_then(|r| country.subdivisions.get(r)).map(String::as_str) } else { None };
        let text = words::holiday(&name, region_name, lang);
        if !out.iter().any(|i| i.date == day && i.text == text) {
            out.push(Item { date: day, kind: Kind::Holiday, text });
        }
    }
    out
}

/// The French school holidays of the zone: their first day off and the day classes resume, in `first..=last`.
fn school(who: &For, first: NaiveDate, last: NaiveDate, lang: &str) -> Vec<Item> {
    if who.country.as_deref() != Some("FR") {
        return Vec::new();
    }
    let Some(zone) = who.school_zone.as_deref() else { return Vec::new() };
    let Some(periods) = SCHOOL.zones.get(zone) else { return Vec::new() };
    let mut out = Vec::new();
    for period in periods {
        let (Some(start), Some(end)) = (date(&period.start), date(&period.end)) else { continue };
        let name =
            period.name.strip_prefix("Début des ").map(words::capitalized).unwrap_or_else(|| period.name.clone());
        let only_start = period.name.starts_with("Début des ");
        let days: Vec<(NaiveDate, SchoolDay)> = if start == end && !only_start {
            vec![(start, SchoolDay::Single)]
        } else if only_start {
            vec![(start, SchoolDay::Start)]
        } else {
            vec![(start, SchoolDay::Start), (end, SchoolDay::End)]
        };
        for (day, which) in days {
            if day >= first && day <= last {
                out.push(Item { date: day, kind: Kind::School, text: words::school(&name, which, zone, lang) });
            }
        }
    }
    out
}

/// Every standard date from `today` for `days` days, the soonest first (clock changes first on a day).
pub fn upcoming(who: &For, today: NaiveDate, days: i64, lang: &str) -> Vec<Item> {
    let last = today + Duration::days(days.max(0));
    let mut out: Vec<Item> = clock_changes(who.zone, today, last)
        .into_iter()
        .map(|c| Item {
            date: c.at.date(),
            kind: Kind::ClockChange,
            text: words::clock_change(c.delta, c.at.time(), lang),
        })
        .collect();
    out.extend(holidays(who, today, last, lang));
    out.extend(school(who, today, last, lang));
    out.sort_by_key(|i| (i.date, i.kind != Kind::ClockChange));
    out
}

/// The one line an agent's context gets when a standard date is within 7 days (two at most, the soonest), else None.
pub fn context_line(who: &For, today: NaiveDate, lang: &str) -> Option<String> {
    let items = upcoming(who, today, 7, lang);
    if items.is_empty() {
        return None;
    }
    let parts: Vec<String> = items.iter().take(2).map(|i| words::dated_line(i.date, &i.text, lang)).collect();
    Some(parts.join(words::separator(lang)))
}

/// The local wall-clock time of a daily routine at `time` in `zone`, said in `other` (its next run, for the travel
/// question): « 7 h à Paris = 15 h à Tokyo ».
pub fn same_instant(time: NaiveTime, zone: Tz, other: Tz, on: NaiveDate) -> Option<NaiveDateTime> {
    let local = zone.from_local_datetime(&on.and_time(time)).earliest()?;
    Some(local.with_timezone(&other).naive_local())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn paris() -> For {
        For {
            zone: "Europe/Paris".parse().unwrap(),
            country: Some("FR".into()),
            region: None,
            school_zone: Some("C".into()),
        }
    }

    fn day(y: i32, m: u32, d: u32) -> NaiveDate {
        NaiveDate::from_ymd_opt(y, m, d).unwrap()
    }

    #[test]
    fn this_weekends_clock_change_in_paris_and_new_york() {
        let changes = clock_changes("Europe/Paris".parse().unwrap(), day(2026, 10, 1), day(2027, 4, 1));
        assert_eq!(
            changes,
            vec![
                Change { at: day(2026, 10, 25).and_hms_opt(3, 0, 0).unwrap(), delta: -3600 },
                Change { at: day(2027, 3, 28).and_hms_opt(2, 0, 0).unwrap(), delta: 3600 },
            ]
        );
        let us = clock_changes("America/New_York".parse().unwrap(), day(2026, 10, 1), day(2026, 11, 30));
        assert_eq!(us, vec![Change { at: day(2026, 11, 1).and_hms_opt(2, 0, 0).unwrap(), delta: -3600 }]);
        assert!(clock_changes("Asia/Tokyo".parse().unwrap(), day(2026, 1, 1), day(2026, 12, 31)).is_empty());
        // Lord Howe changes by half an hour
        let half = clock_changes("Australia/Lord_Howe".parse().unwrap(), day(2026, 1, 1), day(2026, 12, 31));
        assert!(half.iter().all(|c| c.delta.abs() == 1800), "{half:?}");
    }

    #[test]
    fn holidays_of_the_country_and_its_region() {
        let mut who = paris();
        who.school_zone = None;
        let names = |who: &For| -> Vec<String> {
            upcoming(who, day(2026, 3, 30), 10, "fr").into_iter().map(|i| i.text).collect()
        };
        // Good Friday is a holiday in Alsace and Moselle only
        assert_eq!(names(&who), vec!["jour férié : Lundi de Pâques"]);
        who.region = Some("57".into());
        assert!(names(&who).contains(&"jour férié (Moselle) : Vendredi saint".to_string()));
        let us = For {
            zone: "America/New_York".parse().unwrap(),
            country: Some("US".into()),
            region: Some("NY".into()),
            school_zone: None,
        };
        let items = upcoming(&us, day(2026, 11, 20), 10, "fr");
        assert!(items.iter().any(|i| i.text == "jour férié : Thanksgiving Day"), "{items:?}");
        let names: Vec<String> = upcoming(&us, day(2026, 11, 20), 10, "en").into_iter().map(|i| i.text).collect();
        assert!(names.contains(&"public holiday: Thanksgiving Day".to_string()), "{names:?}");
    }

    #[test]
    fn school_holidays_by_zone() {
        let items = upcoming(&paris(), day(2026, 10, 10), 30, "fr");
        let texts: Vec<(String, String)> = items.iter().map(|i| (i.date.to_string(), i.text.clone())).collect();
        assert!(texts.contains(&("2026-10-17".into(), "début des vacances de la Toussaint (zone C, France)".into())));
        assert!(texts.contains(&("2026-10-25".into(), "passage à l'heure d'hiver, on recule d'une heure à 3 h".into())));
        assert!(texts.contains(&("2026-11-01".into(), "jour férié : Toussaint".into())));
        assert!(texts
            .contains(&("2026-11-02".into(), "rentrée après les vacances de la Toussaint (zone C, France)".into())));
        let mut abroad = paris();
        abroad.country = Some("BE".into());
        assert!(upcoming(&abroad, day(2026, 10, 10), 30, "fr").iter().all(|i| i.kind != Kind::School));
    }

    #[test]
    fn the_context_line_only_within_seven_days() {
        let line = context_line(&paris(), day(2026, 10, 24), "fr").unwrap();
        let two = context_line(&paris(), day(2026, 10, 26), "fr").unwrap();
        assert_eq!(
            two,
            "Dimanche 1er novembre : jour férié : Toussaint ; Lundi 2 novembre : rentrée après les vacances de la Toussaint \
(zone C, France)"
        );
        assert_eq!(line, "Dimanche 25 octobre : passage à l'heure d'hiver, on recule d'une heure à 3 h");
        let mut quiet = paris();
        quiet.school_zone = None;
        assert_eq!(
            context_line(&quiet, day(2026, 11, 10), "fr"),
            Some("Mercredi 11 novembre : jour férié : Armistice".into())
        );
        assert_eq!(context_line(&quiet, day(2026, 6, 1), "fr"), None);
        let tokyo = For { zone: "Asia/Tokyo".parse().unwrap(), country: None, region: None, school_zone: None };
        assert_eq!(context_line(&tokyo, day(2026, 10, 24), "en"), None);
    }

    #[test]
    fn every_shipped_country_has_holidays_each_year() {
        for (code, _) in words::COUNTRIES {
            let country = HOLIDAYS.countries.get(code).unwrap_or_else(|| panic!("{code} missing"));
            for year in 2026..=2030 {
                assert!(country.holidays.iter().any(|h| h.date.starts_with(&year.to_string())), "{code} {year}");
            }
        }
        assert_eq!(HOLIDAYS.meta["licence"], "MIT");
        assert!(SCHOOL.meta["licence"].as_str().unwrap().starts_with("Licence Ouverte"));
    }

    #[test]
    fn a_routine_at_seven_in_paris_is_three_in_the_afternoon_in_tokyo() {
        let seven = NaiveTime::from_hms_opt(7, 0, 0).unwrap();
        let at = same_instant(seven, "Europe/Paris".parse().unwrap(), "Asia/Tokyo".parse().unwrap(), day(2026, 10, 26));
        assert_eq!(at, Some(day(2026, 10, 26).and_hms_opt(15, 0, 0).unwrap()));
    }
}
